// ConversationScorecard A QA scorecard result for this conversation. Returned in the `scorecards` array on conversation responses when `include_scorecards=true` is passed.
type ConversationScorecard struct {
	// AiScore The numeric score produced by AI evaluation, if applicable. Null when not AI-scored.
	//
	// Example: 0.9
	AiScore *float64 `json:"ai_score,omitempty"`

	// EvaluatedAt The time the scorecard was last evaluated. Null in the rare case the underlying record's timestamp is not yet set.
	//
	// Example: 1719493065
	EvaluatedAt *int `json:"evaluated_at,omitempty"`

	// Evaluators Per-evaluator results within this scorecard.
	Evaluators *[]ConversationScorecardEvaluator `json:"evaluators,omitempty"`

	// Name The name of the scorecard.
	//
	// Example: Standard QA Review
	Name *string `json:"name,omitempty"`

	// Notes The notes teammates left on the QA review linked to this scorecard entry. Empty when the scorecard has no linked review.
	//
	// Example: [{"author":{"admin_id":"884120017","type":"admin"},"body":"Great empathy in the second reply.","created_at":1734537900,"id":"9001","updated_at":1734537900}]
	Notes *[]ConversationScorecardNote `json:"notes,omitempty"`

	// Passed Whether the conversation passed the scorecard. Null when the scorecard has not been scored.
	//
	// Example: true
	Passed *bool `json:"passed,omitempty"`

	// ReviewStatus The status of the review of this scorecard, as shown in the QA reviews list in Intercom. `unreviewed` while the review is waiting for a reviewer's verdict; `submitted` once the review has been submitted; `passed_review`, `needs_fix`, `wont_fix` or `fix_complete` when a teammate set a specific outcome. Null when no review exists for this scorecard.
	//
	// Example: submitted
	ReviewStatus *ConversationScorecardReviewStatus `json:"review_status,omitempty"`

	// ReviewedTeammate The teammate (or AI agent) whose handling of the conversation was reviewed by this scorecard.
	ReviewedTeammate *ConversationScorecardReviewedTeammate `json:"reviewed_teammate,omitempty"`

	// Reviewer Who the review of this scorecard is assigned to. `ai` when it is assigned to Fin; `admin` when it is assigned to a teammate. Null when no review exists for this scorecard or the review is unassigned.
	Reviewer *ConversationScorecardReviewer `json:"reviewer,omitempty"`

	// RevisedBy Who last changed the review of this scorecard after it was submitted. `ai` when Fin made the change; `admin` when a teammate did. Null while the review is unreviewed, when it has not been changed since it was submitted, or when no review exists for this scorecard.
	RevisedBy *ConversationScorecardRevisedBy `json:"revised_by,omitempty"`

	// Score The numeric score for the scorecard. Null when the scorecard has not been scored.
	//
	// Example: 0.85
	Score *float64 `json:"score,omitempty"`

	// ScorecardId The unique identifier of the scorecard definition.
	//
	// Example: 67890
	ScorecardId *string `json:"scorecard_id,omitempty"`

	// ScorecardType The type of scorecard.
	//
	// Example: human
	ScorecardType *string `json:"scorecard_type,omitempty"`

	// ScorecardVersionId The unique identifier of the specific scorecard version that produced this result.
	//
	// Example: 67891
	ScorecardVersionId *string `json:"scorecard_version_id,omitempty"`

	// SubmittedBy Who last submitted the review of this scorecard, which can differ from the `reviewer` it is assigned to. `ai` when Fin submitted it; `admin` when a teammate did. Null while the review is unreviewed or when no review exists for this scorecard.
	SubmittedBy *ConversationScorecardSubmittedBy `json:"submitted_by,omitempty"`
}

// ConversationScorecardReviewStatus The status of the review of this scorecard, as shown in the QA reviews list in Intercom. `unreviewed` while the review is waiting for a reviewer's verdict; `submitted` once the review has been submitted; `passed_review`, `needs_fix`, `wont_fix` or `fix_complete` when a teammate set a specific outcome. Null when no review exists for this scorecard.
//
// Example: submitted
type ConversationScorecardReviewStatus string

// ConversationScorecardEvaluator A single evaluator within a scorecard, including its result for this conversation.
type ConversationScorecardEvaluator struct {
	// EvaluatorId The unique identifier of the evaluator (criterion) within the scorecard.
	//
	// Example: 54321
	EvaluatorId *string `json:"evaluator_id,omitempty"`

	// Name The name of the evaluator (criterion). Null if the evaluator's name could not be resolved.
	//
	// Example: Tone of voice
	Name *string `json:"name,omitempty"`

	// Result The evaluator's result for this conversation. Null if the evaluator was not scored.
	Result *ConversationScorecardEvaluatorResult `json:"result,omitempty"`
}

// ConversationScorecardEvaluatorReason A single structured reason assigned to an evaluator's result.
type ConversationScorecardEvaluatorReason struct {
	// Name The name of the reason. Null if the reason's name could not be resolved.
	//
	// Example: Clear and concise
	Name *string `json:"name,omitempty"`
}

// ConversationScorecardEvaluatorResult The outcome of a single evaluator within a scorecard.
type ConversationScorecardEvaluatorResult struct {
	// OtherText Free-text entered by the reviewer to supplement or stand in for the structured `reason_ids` — typically captured when the reviewer selects an "Other" option or adds a custom note. Null when not provided.
	//
	// Example: Agent acknowledged the issue but missed the follow-up question about billing.
	OtherText *string `json:"other_text,omitempty"`

	// ReasonIds Identifiers for structured reasons assigned to the result, if any.
	//
	// Example: ["101","102"]
	ReasonIds *[]string `json:"reason_ids,omitempty"`

	// Reasoning A free-text explanation of the result.
	//
	// Example: The agent acknowledged the issue and resolved it within the same response.
	Reasoning *string `json:"reasoning,omitempty"`

	// Reasons The structured reasons chosen for this result. Omitted when none were chosen.
	//
	// Example: [{"name":"Clear and concise"},{"name":"Empathetic tone"}]
	Reasons *[]ConversationScorecardEvaluatorReason `json:"reasons,omitempty"`

	// Source The origin of the result (for example, `ai` or `human`).
	//
	// Example: ai
	Source *string `json:"source,omitempty"`

	// Value The evaluator's selected value (typically a label such as `pass`, `fail`, or a category identifier).
	//
	// Example: pass
	Value *string `json:"value,omitempty"`

	// ValueLabel The label of the rating option matching `value` (for example `Needs improvement`). Omitted when the label could not be resolved.
	//
	// Example: Pass
	ValueLabel *string `json:"value_label,omitempty"`
}

// ConversationScorecardNote A note a teammate left on the QA review of this scorecard.
